import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"Example fixtures policy","description":"","frontmatter":{},"headers":[],"relativePath":"EXAMPLE-FIXTURES.md","filePath":"EXAMPLE-FIXTURES.md"}'),n={name:"EXAMPLE-FIXTURES.md"};function i(s,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="example-fixtures-policy" tabindex="-1">Example fixtures policy <a class="header-anchor" href="#example-fixtures-policy" aria-label="Permalink to &quot;Example fixtures policy&quot;">​</a></h1><blockquote><p><a href="./EXAMPLE-FIXTURES">🇬🇧 English</a> • <a href="./EXAMPLE-FIXTURES.ja">🇯🇵 日本語</a></p></blockquote><p>This document explains which examples have been retrofitted with a &quot;completed reference fixture under <code>tests/fixtures/</code>&quot; and which examples are intentionally out of scope. It exists so contributors can predict, without reading commit history, whether a given example is meant to be walked through 0 → 1 with the skill chain or simply read as-is.</p><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Group</th><th>Examples</th><th>Has <code>tests/fixtures/&lt;name&gt;/</code>?</th><th>What to expect</th></tr></thead><tbody><tr><td>Contract-bearing fixtures</td><td>mint-nft / defi-swap / nextjs-token-gating / nft-marketplace</td><td>✅ Yes</td><td><code>examples/&lt;name&gt;/{test,hardhat-test,tests}/</code> is gitignored. The skill chain regenerates tests there. The completed reference suite lives under <code>tests/fixtures/&lt;name&gt;/</code>.</td></tr><tr><td>Connection-only fixture</td><td>basic-connect</td><td>✅ Yes (e2e-test only)</td><td>Same shape but Foundry / Hardhat lanes are not applicable because the example has no Solidity contract of its own.</td></tr><tr><td>e2e-only examples (17)</td><td>nextjs-aa-erc4337 / nextjs-aa-smart-account / nextjs-bridge / nextjs-dao-vote / nextjs-ens-resolver / nextjs-erc1155-game / nextjs-event-history / nextjs-lending / nextjs-multi-chain / nextjs-permit-swap / nextjs-safe-multisig / nextjs-staking / nextjs-vesting / nextjs-wagmi-rainbow / nextjs-walletconnect-v2 / nextjs-zk-verifier / vite-react-wagmi</td><td>❌ No (out of scope)</td><td><code>examples/&lt;name&gt;/tests/</code> stays tracked. The retrofit walkthrough is not the recommended path for these examples. Read or fork them as-is.</td></tr></tbody></table><blockquote><p>Note — <code>nextjs-walletconnect-v2</code> and <code>nextjs-safe-multisig</code> (added in PR #305 / #306) are Level B mock examples per <code>docs/MOCK-DESIGN.md</code>. They demonstrate one mock pattern each (WalletConnect v2 in-memory relay / Safe v1.4 semantics in TS) and are treated as e2e-only for the same reason as the others — no in-repo Solidity surface for <code>/kiwa-forge</code> / <code>/kiwa-hardhat</code> to own.</p></blockquote><h2 id="why-the-e2e-only-examples-are-out-of-scope" tabindex="-1">Why the e2e-only examples are out of scope <a class="header-anchor" href="#why-the-e2e-only-examples-are-out-of-scope" aria-label="Permalink to &quot;Why the e2e-only examples are out of scope&quot;">​</a></h2><p>These examples exist to demonstrate one integration pattern each (account abstraction, bridging, voting, ENS lookup, multi-chain, ZK verifier, etc.) on top of an upstream contract that kiwa does not own. There are three concrete reasons we do not push them through the same fixtures-retrofit treatment as the four contract-bearing examples.</p><ul><li>They have no Solidity contract under <code>examples/&lt;name&gt;/contracts/</code> for kiwa to own as a source of truth. The Foundry / Hardhat lanes therefore have no surface area.</li><li>The Playwright spec is typically demonstrating an end-to-end pattern with a specific helper composition (multi-step approval, paymaster setup, ZK proof generation). Splitting it into a &quot;workbench&quot; vs. &quot;finished fixture&quot; pair adds friction without clarifying the pattern.</li><li>We want the e2e-only examples to be readable in one place. Forcing the retrofit walkthrough onto them would gitignore <code>tests/</code> and require contributors to walk the skill chain just to see what the integration looks like.</li></ul><p>The four contract-bearing examples are different because they exist precisely to demonstrate the skill chain from contract spec to e2e flow, so the &quot;workbench + finished fixture&quot; split is the whole point.</p><h2 id="how-to-walk-an-e2e-only-example" tabindex="-1">How to walk an e2e-only example <a class="header-anchor" href="#how-to-walk-an-e2e-only-example" aria-label="Permalink to &quot;How to walk an e2e-only example&quot;">​</a></h2><p>If you want to understand or extend an e2e-only example, read its <code>tests/*.spec.ts</code> directly, then either fork the example or copy the relevant helper into your own project. The <code>/kiwa-play</code> skill can still be invoked against these examples — it will read the existing spec rather than scaffold a new one.</p><h2 id="future-direction" tabindex="-1">Future direction <a class="header-anchor" href="#future-direction" aria-label="Permalink to &quot;Future direction&quot;">​</a></h2><p>If a future change introduces a Solidity contract into one of the e2e-only examples (for instance, replacing a Goerli-deployed upstream contract with an in-repo <code>contracts/</code> source), that specific example becomes a candidate for fixtures retrofit on the same footing as the four current ones. The decision is made per example, not as a sweep.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../tests/docs/README">tests/docs/README.md</a> — entry point for the skill-chain test docs</li><li><a href="./../tests/docs/retrofit-existing-dapp">tests/docs/retrofit-existing-dapp.md</a> — walkthrough for the contract-bearing examples</li><li><a href="./../examples/mint-nft/README">examples/mint-nft/README.md</a> — reference shape of the &quot;workbench + finished fixture&quot; split</li><li><a href="./COMPARISON">docs/COMPARISON.md</a> — how kiwa positions itself versus Synpress / dappwright / wallet-mock</li></ul>',16)])])}const m=t(n,[["render",i]]);export{u as __pageData,m as default};
